package bowling

import "errors"

// Game keeps track of the state of a bowling game and its score.
type Game struct {
	rolls         []int // every roll recorded so far
	frame         int   // current frame, 0-indexed (0-9)
	rollInFrame   int   // which roll within the current frame (0, 1, or 2)
	pinsRemaining int   // pins still standing on the lane before the next roll
	gameOver      bool  // true once all ten frames are complete
}

func NewGame() *Game {
	return &Game{
		rolls:         []int{},
		frame:         0,
		rollInFrame:   0,
		pinsRemaining: 10,
		gameOver:      false,
	}
}

// Roll records a throw of the given number of pins and advances the game state.
func (g *Game) Roll(pins int) error {
	if g.gameOver {
		return errors.New("Cannot roll after game is over")
	}
	if pins < 0 {
		return errors.New("Negative roll is invalid")
	}
	if pins > g.pinsRemaining {
		return errors.New("Pin count exceeds pins on the lane")
	}

	g.rolls = append(g.rolls, pins)

	if g.frame < 9 {
		// Frames 1-9: a frame is a single strike or two rolls.
		if g.rollInFrame == 0 && pins == 10 {
			g.advanceFrame()
		} else if g.rollInFrame == 0 {
			g.rollInFrame = 1
			g.pinsRemaining = 10 - pins
		} else {
			g.advanceFrame()
		}
	} else {
		// Frame 10: spare or strike earns one or two fill balls.
		if g.rollInFrame == 2 {
			g.gameOver = true
		} else {
			g.rollInFrame++
			if g.pinsRemaining == 10 {
				// A fresh set of pins was standing; a strike keeps it fresh.
				if pins == 10 {
					g.pinsRemaining = 10
				} else {
					g.pinsRemaining = 10 - pins
				}
			} else {
				// This roll completed a spare; the fill ball gets a fresh set.
				g.pinsRemaining = 10
			}
		}
	}
	return nil
}

func (g *Game) advanceFrame() {
	g.frame++
	g.rollInFrame = 0
	g.pinsRemaining = 10
	if g.frame >= 10 {
		g.gameOver = true
	}
}

// Score returns the total score for a completed game.
func (g *Game) Score() (int, error) {
	if !g.gameOver {
		return 0, errors.New("Score cannot be taken until the end of the game")
	}

	rolls := g.rolls
	score := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case rolls[i] == 10: // strike: 10 plus the next two rolls
			score += 10 + rolls[i+1] + rolls[i+2]
			i++
		case rolls[i]+rolls[i+1] == 10: // spare: 10 plus the next roll
			score += 10 + rolls[i+2]
			i += 2
		default: // open frame
			score += rolls[i] + rolls[i+1]
			i += 2
		}
	}
	return score, nil
}

